import math
h = [2, 1]
heads = {'cup': ([1, 1], 0), 'book': ([2, -1], 0), 'ball': ([0, 1], 0.5)}
scores = {k: sum(a * b for a, b in zip(w, h)) + b for k, (w, b) in heads.items()}
top = max(scores.values())
e = {k: math.exp(s - top) for k, s in scores.items()}
p = {k: v / sum(e.values()) for k, v in e.items()}
print(scores, {k: round(v, 4) for k, v in p.items()})
print(round(-math.log(p['cup']), 4))

boxes = {'A': ((0, 0, 10, 10), 0.95), 'B': ((1, 1, 11, 11), 0.90), 'C': ((20, 0, 30, 10), 0.85),
         'D': ((6, 0, 16, 10), 0.80), 'E': ((21, 1, 31, 11), 0.70)}
def iou(a, b):
    w = max(0, min(a[2], b[2]) - max(a[0], b[0])); h = max(0, min(a[3], b[3]) - max(a[1], b[1]))
    area = lambda r: (r[2] - r[0]) * (r[3] - r[1])
    return w * h / (area(a) + area(b) - w * h)
left = sorted(boxes, key=lambda k: -boxes[k][1])
step = 0
while left:
    kept = left.pop(0)
    survivors = []
    for other in left:
        step += 1
        value = iou(boxes[kept][0], boxes[other][0])
        decision = 'suppress' if value > 0.5 else 'keep'
        print('\t'.join([str(step), kept, other, f'{value:.2f}', decision]))
        if decision == 'keep':
            survivors.append(other)
    left = survivors

